// Package repository stores passkeys through the storage adapter.
package repository

import (
	"context"
	"errors"
	"fmt"

	"github.com/better-go-auth/goauth/src/adapter"
	"github.com/better-go-auth/goauth/src/adapter/recordbind"
	pkmodels "github.com/better-go-auth/goauth/src/plugins/passkey/models"
	"github.com/better-go-auth/goauth/src/schema"
)

// IPasskeyRepo is the storage of the passkey plugin. Find methods return (nil, nil) when nothing matches.
type IPasskeyRepo interface {
	// Create inserts pk and fills in its ID (generated by the adapter or the database when empty).
	Create(ctx context.Context, pk *pkmodels.Passkey) error
	FindByID(ctx context.Context, id string) (*pkmodels.Passkey, error)
	FindByCredentialID(ctx context.Context, credentialID string) (*pkmodels.Passkey, error)
	// ListByUser returns the user's passkeys, oldest first.
	ListByUser(ctx context.Context, userID string) ([]pkmodels.Passkey, error)
	// UpdateCounter stores the signature counter reported by the last assertion.
	UpdateCounter(ctx context.Context, id string, counter int64) error
	// UpdateName renames a passkey and returns the updated row (nil when it doesn't exist).
	UpdateName(ctx context.Context, id, name string) (*pkmodels.Passkey, error)
	Delete(ctx context.Context, id string) error
	// DeleteByUser removes every passkey of a user (user deletion cleanup).
	DeleteByUser(ctx context.Context, userID string) error
}

// adapterRepo stores passkeys through the storage adapter (any backend; joins the transaction in ctx).
type adapterRepo struct {
	store adapter.Adapter
	b     *recordbind.Binding[pkmodels.Passkey]
}

// New returns the passkey repository on store. reg must declare the passkey model (pkmodels.Schema).
func New(store adapter.Adapter, reg *schema.Registry) (IPasskeyRepo, error) {
	if store == nil || reg == nil {
		return nil, errors.New("passkey: a storage adapter and the schema registry are required")
	}
	b, err := recordbind.New[pkmodels.Passkey](reg, pkmodels.ModelPasskey,
		recordbind.Field{Go: "ID", Name: "id"},
		recordbind.Field{Go: "Name", Name: "name"},
		recordbind.Field{Go: "PublicKey", Name: "publicKey"},
		recordbind.Field{Go: "UserID", Name: "userId"},
		recordbind.Field{Go: "CredentialID", Name: "credentialID"},
		recordbind.Field{Go: "Counter", Name: "counter"},
		recordbind.Field{Go: "DeviceType", Name: "deviceType"},
		recordbind.Field{Go: "BackedUp", Name: "backedUp"},
		recordbind.Field{Go: "Transports", Name: "transports"},
		recordbind.Field{Go: "CreatedAt", Name: "createdAt"},
		recordbind.Field{Go: "AAGUID", Name: "aaguid"},
	)
	if err != nil {
		return nil, err
	}
	return &adapterRepo{store: store, b: b}, nil
}

func eq(field string, v any) []adapter.Where { return []adapter.Where{{Field: field, Value: v}} }

func (r *adapterRepo) Create(ctx context.Context, pk *pkmodels.Passkey) error {
	// Step 1: insert
	rec, err := r.store.Create(ctx, r.b.Model(), r.b.Record(pk))
	if err != nil {
		return fmt.Errorf("passkey: create: %w", err)
	}
	// Step 2: hand the stored row (generated id) back to the caller
	stored, err := r.b.Decode(rec)
	if err != nil {
		return err
	}
	*pk = *stored
	return nil
}

// findOne returns the passkey matching field = value, or (nil, nil).
func (r *adapterRepo) findOne(ctx context.Context, field, value string) (*pkmodels.Passkey, error) {
	rec, err := r.store.FindOne(ctx, r.b.Model(), eq(field, value))
	if errors.Is(err, adapter.ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("passkey: find: %w", err)
	}
	return r.b.Decode(rec)
}

func (r *adapterRepo) FindByID(ctx context.Context, id string) (*pkmodels.Passkey, error) {
	return r.findOne(ctx, "id", id)
}

func (r *adapterRepo) FindByCredentialID(ctx context.Context, credentialID string) (*pkmodels.Passkey, error) {
	return r.findOne(ctx, "credentialID", credentialID)
}

func (r *adapterRepo) ListByUser(ctx context.Context, userID string) ([]pkmodels.Passkey, error) {
	recs, err := r.store.FindMany(ctx, r.b.Model(), adapter.Query{
		Where: eq("userId", userID),
		Sort:  []adapter.SortBy{{Field: "createdAt"}, {Field: "id"}},
	})
	if err != nil {
		return nil, fmt.Errorf("passkey: list: %w", err)
	}
	return r.b.DecodeAll(recs)
}

func (r *adapterRepo) UpdateCounter(ctx context.Context, id string, counter int64) error {
	_, err := r.store.UpdateMany(ctx, r.b.Model(), eq("id", id), adapter.Record{"counter": counter})
	return err
}

func (r *adapterRepo) UpdateName(ctx context.Context, id, name string) (*pkmodels.Passkey, error) {
	// better-auth's adapter.update: the updated row, or nothing when the id doesn't exist
	rec, err := r.store.Update(ctx, r.b.Model(), eq("id", id), adapter.Record{"name": name})
	if errors.Is(err, adapter.ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("passkey: rename: %w", err)
	}
	return r.b.Decode(rec)
}

func (r *adapterRepo) Delete(ctx context.Context, id string) error {
	_, err := r.store.DeleteMany(ctx, r.b.Model(), eq("id", id))
	return err
}

func (r *adapterRepo) DeleteByUser(ctx context.Context, userID string) error {
	_, err := r.store.DeleteMany(ctx, r.b.Model(), eq("userId", userID))
	return err
}
